// Everything the dashboard shows is computed here, so the browser only renders.
const cfg = $('Config').first().json;
const rows = (n) => $(n).all().map(i => i.json);
const leads    = rows('Read Leads').filter(l => l && (l.lead_id || l.phone));
const projects = rows('Read Projects').filter(p => p && p.project_name);
const visits   = rows('Read Visits').filter(v => v && v.event_id);
const messages = rows('Read Messages').filter(m => m && m.timestamp);

const TZ = cfg.TIMEZONE || 'Asia/Kolkata';
const now = Date.now();
const ms = (v) => { const t = new Date(v || 0).getTime(); return Number.isFinite(t) && t > 0 ? t : 0; };
const daysSince = (v) => ms(v) ? (now - ms(v)) / 86400000 : null;
const day = (v) => ms(v) ? new Date(ms(v)).toLocaleDateString('en-CA', { timeZone: TZ }) : '';
const today = new Date(now).toLocaleDateString('en-CA', { timeZone: TZ });
const grade = (l) => String(l.grade || '').toUpperCase() || 'UNGRADED';
const status = (l) => String(l.status || 'New').trim();
const num = (v) => Number(v || 0) || 0;
const CLOSED = ['Booked', 'Lost', 'Dropped'];

// ---- cadence, mirrored from RE-04 / RE-05 so the queue matches what will actually send
const CADENCE = { HOT: num(cfg.CADENCE_HOT_DAYS), WARM: num(cfg.CADENCE_WARM_DAYS), COLD: num(cfg.CADENCE_COLD_DAYS), JUNK: 999 };
const MAX_FOLLOWUPS = num(cfg.MAX_FOLLOWUPS);
const HOLD_HOURS = num(cfg.CONVERSATION_HOLD_HOURS);
const SLA_MINUTES = num(cfg.SLA_MINUTES) || 15;

function nurture(l) {
  const st = status(l);
  if (CLOSED.includes(st)) return { state: 'closed', due_in_days: null };
  if (st === 'Engaged') {
    const quiet = (now - ms(l.last_inbound_at || l.last_touch)) / 3600000;
    if (quiet < HOLD_HOURS) return { state: 'in_conversation', due_in_days: Math.round((HOLD_HOURS - quiet) / 24 * 10) / 10 };
  }
  if (num(l.followup_count) >= MAX_FOLLOWUPS) return { state: 'at_cap', due_in_days: null };
  const g = grade(l);
  if (g === 'JUNK') return { state: 'junk', due_in_days: null };
  const interval = CADENCE[g] ?? CADENCE.WARM;
  const since = daysSince(l.last_touch || l.created_at);
  if (since === null) return { state: 'unknown', due_in_days: null };
  const left = interval - since;
  return { state: left <= 0 ? 'due' : 'waiting', due_in_days: Math.round(left * 10) / 10 };
}
const withNurture = leads.map(l => ({ ...l, __n: nurture(l) }));

const countStatus = (s) => leads.filter(l => status(l) === s).length;
const countGrade  = (g) => leads.filter(l => grade(l) === g).length;
const live = leads.filter(l => !CLOSED.includes(status(l)));
const replied = leads.filter(l => ms(l.last_inbound_at) > 0).length;
const engagedContent = leads.filter(l => ms(l.details_sent) > 0 || ms(l.brochure_sent) > 0).length;
const visitCount = countStatus('Visit Scheduled');
const bookedCount = countStatus('Booked');
const pct = (a, b) => b ? Math.round((a / b) * 1000) / 10 : 0;

// ---- sources, one row per channel actually seen in the data
const srcMap = {};
for (const l of leads) {
  const s = (l.source || 'unknown').toString().trim() || 'unknown';
  srcMap[s] = srcMap[s] || { source: s, total: 0, hot: 0, junk: 0, replied: 0, visits: 0, booked: 0 };
  const e = srcMap[s];
  e.total++;
  if (grade(l) === 'HOT') e.hot++;
  if (grade(l) === 'JUNK') e.junk++;
  if (ms(l.last_inbound_at) > 0) e.replied++;
  if (status(l) === 'Visit Scheduled') e.visits++;
  if (status(l) === 'Booked') e.booked++;
}
const sources = Object.values(srcMap).sort((a, b) => b.total - a.total);

// ---- projects
const projMap = {};
for (const p of projects) projMap[p.project_name] = { project: p.project_name, price_range: p.price_range || '', leads: 0, hot: 0, visits: 0, booked: 0, has_brochure: !!String(p.brochure_url || '').trim(), photos: [p.image_1, p.image_2, p.image_3].filter(x => String(x || '').trim()).length };
for (const l of leads) {
  const k = l.project;
  if (!k) continue;
  projMap[k] = projMap[k] || { project: k, price_range: '', leads: 0, hot: 0, visits: 0, booked: 0, has_brochure: false, photos: 0, missing_from_projects_tab: true };
  projMap[k].leads++;
  if (grade(l) === 'HOT') projMap[k].hot++;
  if (status(l) === 'Visit Scheduled') projMap[k].visits++;
  if (status(l) === 'Booked') projMap[k].booked++;
}
const projectRows = Object.values(projMap).sort((a, b) => b.leads - a.leads);

// ---- activity feed, newest first
const feed = messages.slice()
  .sort((a, b) => ms(b.timestamp) - ms(a.timestamp))
  .slice(0, 60)
  .map(m => ({
    at: m.timestamp, lead_id: m.lead_id || '', phone: m.phone || '',
    direction: (m.direction || '').toLowerCase(), type: m.type || '',
    action: m.action || '', body: String(m.body || '').slice(0, 220), status: m.status || ''
  }));
const byId = {};
for (const l of leads) if (l.lead_id) byId[l.lead_id] = l.name;
for (const f of feed) f.name = byId[f.lead_id] || '';

// ---- messages per day, last 14 days
const spark = [];
for (let i = 13; i >= 0; i--) {
  const d = new Date(now - i * 86400000).toLocaleDateString('en-CA', { timeZone: TZ });
  spark.push({
    day: d,
    inbound: messages.filter(m => day(m.timestamp) === d && (m.direction || '').toLowerCase() === 'inbound').length,
    outbound: messages.filter(m => day(m.timestamp) === d && (m.direction || '').toLowerCase() === 'outbound').length
  });
}

// ---- visits
const upcoming = visits
  .filter(v => ms(v.visit_start_iso) >= now && String(v.status || 'Scheduled') === 'Scheduled')
  .sort((a, b) => ms(a.visit_start_iso) - ms(b.visit_start_iso))
  .slice(0, 12);
const past = visits.filter(v => ms(v.visit_start_iso) < now);

// ---- follow-up queue
const dueNow = withNurture.filter(l => l.__n.state === 'due')
  .sort((a, b) => (daysSince(b.last_touch) || 0) - (daysSince(a.last_touch) || 0));
const atCap = withNurture.filter(l => l.__n.state === 'at_cap');
const inConversation = withNurture.filter(l => l.__n.state === 'in_conversation');

const slim = (l) => ({
  lead_id: l.lead_id, name: l.name || '(no name)', phone: l.phone || '', wa_id: l.wa_id || '',
  email: l.email || '', project: l.project || '', source: l.source || 'unknown',
  grade: grade(l), score: num(l.score), status: status(l), owner: l.owner || '',
  followup_count: num(l.followup_count), touch_count: num(l.touch_count),
  created_at: l.created_at || '', last_touch: l.last_touch || '', last_inbound_at: l.last_inbound_at || '',
  last_action: l.last_action || '', next_action: l.next_action || '', ai_summary: l.ai_summary || '',
  visit_at: l.visit_at || '', nurture: l.__n
});

// ---- pipeline health, derived from the data the workflows actually write
const maxOf = (arr, f) => arr.reduce((a, x) => Math.max(a, ms(f(x))), 0);
const lastLead = maxOf(leads, l => l.created_at);
const lastInbound = maxOf(messages.filter(m => (m.direction || '').toLowerCase() === 'inbound'), m => m.timestamp);
const lastOutbound = maxOf(messages.filter(m => (m.direction || '').toLowerCase() === 'outbound'), m => m.timestamp);
const lastFollowup = maxOf(leads, l => l.last_followup_at);
const lastVisitBooked = maxOf(visits, v => v.created_at);
const iso = (t) => t ? new Date(t).toISOString() : '';

const payload = {
  ok: true,
  generated_at: new Date(now).toISOString(),
  company: cfg.COMPANY_NAME,
  timezone: TZ,
  config: { max_followups: MAX_FOLLOWUPS, cadence: CADENCE, hold_hours: HOLD_HOURS, sla_minutes: SLA_MINUTES },
  kpis: {
    total_leads: leads.length,
    live: live.length,
    new_leads: countStatus('New'),
    engaged: countStatus('Engaged'),
    nurturing: countStatus('Nurturing'),
    visit_scheduled: visitCount,
    booked: bookedCount,
    lost: countStatus('Lost') + countStatus('Dropped'),
    hot: countGrade('HOT'), warm: countGrade('WARM'), cold: countGrade('COLD'),
    junk: countGrade('JUNK'), ungraded: countGrade('UNGRADED'),
    unowned: live.filter(l => !String(l.owner || '').trim()).length,
    breached_sla: live.filter(l => status(l) === 'New' && ms(l.created_at) && (now - ms(l.created_at)) / 60000 > SLA_MINUTES).length,
    at_cap: atCap.length,
    in_conversation: inConversation.length,
    due_now: dueNow.length,
    leads_today: leads.filter(l => day(l.created_at) === today).length,
    messages_today: messages.filter(m => day(m.timestamp) === today).length,
    visits_upcoming: upcoming.length,
    visits_done: past.length,
    reply_rate: pct(replied, leads.length),
    visit_rate: pct(visitCount + bookedCount, leads.length),
    booking_rate: pct(bookedCount, leads.length)
  },
  funnel: [
    { stage: 'Lead captured', count: leads.length },
    { stage: 'WhatsApp menu delivered', count: leads.filter(l => ms(l.last_touch) > 0).length },
    { stage: 'Buyer replied', count: replied },
    { stage: 'Details or brochure sent', count: engagedContent },
    { stage: 'Site visit scheduled', count: visitCount + bookedCount },
    { stage: 'Booked', count: bookedCount }
  ],
  grades: [
    { grade: 'HOT', count: countGrade('HOT') },
    { grade: 'WARM', count: countGrade('WARM') },
    { grade: 'COLD', count: countGrade('COLD') },
    { grade: 'JUNK', count: countGrade('JUNK') },
    { grade: 'UNGRADED', count: countGrade('UNGRADED') }
  ],
  sources,
  projects: projectRows,
  activity: feed,
  message_trend: spark,
  upcoming_visits: upcoming.map(v => ({
    event_id: v.event_id, name: v.name || '', phone: v.phone || '', project: v.project || '',
    when: v.visit_start_ist || '', when_iso: v.visit_start_iso || '',
    sales_manager: v.sales_manager || '', calendar_link: v.calendar_link || '', status: v.status || 'Scheduled'
  })),
  followups: { due_now: dueNow.slice(0, 40).map(slim), at_cap: atCap.slice(0, 40).map(slim), in_conversation: inConversation.slice(0, 40).map(slim) },
  leads: withNurture
    .slice()
    .sort((a, b) => ms(b.last_touch || b.created_at) - ms(a.last_touch || a.created_at))
    .slice(0, 300)
    .map(slim),
  health: {
    last_lead_at: iso(lastLead),
    last_inbound_at: iso(lastInbound),
    last_outbound_at: iso(lastOutbound),
    last_followup_at: iso(lastFollowup),
    last_visit_booked_at: iso(lastVisitBooked),
    rows: { leads: leads.length, projects: projects.length, visits: visits.length, messages: messages.length },
    warnings: [
      projects.length === 0 ? 'The Projects tab is empty - the bot has nothing to send for View Details or Download Brochure.' : null,
      projectRows.some(p => p.missing_from_projects_tab) ? 'Some leads name a project that has no row in the Projects tab.' : null,
      projectRows.some(p => !p.missing_from_projects_tab && !p.has_brochure) ? 'At least one project has no brochure_url - Download Brochure will fall back to the apology message.' : null,
      projectRows.some(p => !p.missing_from_projects_tab && p.photos === 0) ? 'At least one project has no photos - View Details will send text only.' : null,
      leads.length && !lastInbound ? 'No inbound WhatsApp message has ever been logged - check the Meta webhook and your tunnel.' : null
    ].filter(Boolean)
  }
};
return [{ json: payload }];
